export const translations = Object.fromEntries(Object.entries(rows).map(([language, data]) => [language, Object.fromEntries(groups.flatMap((keys, index) => {
  const values = data[index].split('|');
  if (keys.length !== values.length) throw Error(`${language}: translation group ${index}, expected ${keys.length}, found ${values.length}`);
  return keys.map((key, i) => [key, values[i]]);
}))]));
